import random

def strategy(history, rng):
    if not history:
        return 'C'
    n = len(history)
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    if n == 1:
        return 'C'
    if n == 2:
        return 'C'
    if n == 3:
        return 'C'
    if n == 4:
        return 'C'
    if n == 5:
        return 'C'
    if n >= 6:
        if my[-1] == 'D' and op[-1] == 'C':
            return 'C'
        if op[-1] == 'D' and my[-1] == 'C':
            return 'C'
        op_c = 0
        op_d = 0
        for i in range(n):
            if op[i] == 'C':
                op_c += 1
            else:
                op_d += 1
        if op_d == 0:
            return 'D'
        if op_c == 0:
            if n >= 10:
                return 'C'
            return 'D'
        last10 = op[-10:]
        c10 = last10.count('C')
        d10 = last10.count('D')
        if d10 == 0:
            return 'D'
        if c10 == 0:
            if n >= 20:
                if op[-5:].count('C') >= 2:
                    return 'C'
                return 'D'
            return 'D'
        if n >= 10:
            total_d = op_d
            if total_d * 3 > n:
                if op[-1] == 'D':
                    return 'D'
                return 'C'
            if op[-1] == 'D' and op[-2] == 'D':
                return 'D'
            if op[-1] == 'C' and op[-2] == 'C' and n >= 8:
                return 'C'
        return 'C'
